From 44299c5f9b17218568fa99afcd4bbbb5d3b423e9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:42:54 +0100
Subject: [PATCH] libkworkspace: show a notification when going to sleep fails

When logind refused to sleep, for example because an earlier request was
still in progress, nothing visible happened. Now a notification shows
the error from logind, unless the user cancelled authentication.

BUG: 483107
---
 libkworkspace/CMakeLists.txt               |  1 +
 libkworkspace/sessionmanagementbackend.cpp | 32 +++++++++++++++++++---
 2 files changed, 29 insertions(+), 4 deletions(-)

diff --git a/libkworkspace/CMakeLists.txt b/libkworkspace/CMakeLists.txt
index 6f85f0af7d..800bc831c2 100644
--- a/libkworkspace/CMakeLists.txt
+++ b/libkworkspace/CMakeLists.txt
@@ -49,6 +49,7 @@ target_link_libraries(kworkspace
         Qt::DBus
         Qt::WaylandClient
         KF6::I18n
+        KF6::Notifications
         KF6::WindowSystem
         KF6::Service
 )
diff --git a/libkworkspace/sessionmanagementbackend.cpp b/libkworkspace/sessionmanagementbackend.cpp
index d0742bfb9a..8a73ddf43b 100644
--- a/libkworkspace/sessionmanagementbackend.cpp
+++ b/libkworkspace/sessionmanagementbackend.cpp
@@ -13,14 +13,38 @@
 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
 #include <QDBusPendingCallWatcher>
+#include <QEventLoopLocker>

 #include <KConfigGroup>
+#include <KLocalizedString>
+#include <KNotification>
 #include <iostream>

+#include "libkworkspace_debug.h"
 #include "login1_manager_interface.h"

 static SessionBackend *s_backend = nullptr;

+static void notifySleepFailed(QDBusPendingReply<> reply, const QString &title)
+{
+    reply.waitForFinished();
+    if (!reply.isError()) {
+        return;
+    }
+    // the user cancelled the authentication dialog
+    if (reply.error().type() == QDBusError::AccessDenied
+        || reply.error().name() == QLatin1String("org.freedesktop.DBus.Error.InteractiveAuthorizationRequired")) {
+        return;
+    }
+    qCWarning(LIBKWORKSPACE_DEBUG) << "Failed to sleep:" << reply.error().name() << reply.error().message();
+    auto notification = KNotification::event(KNotification::Error, title, reply.error().message(), QStringLiteral("system-suspend"));
+    // callers like the logout greeter quit right after this, keep them running until the notification is out
+    auto eventLoopLocker = new QEventLoopLocker;
+    QObject::connect(notification, &QObject::destroyed, [eventLoopLocker] {
+        delete eventLoopLocker;
+    });
+}
+
 SessionBackend *SessionBackend::self()
 {
     static QMutex mutex;
@@ -189,22 +213,22 @@ void LogindSessionBackend::suspend()
 {
     // these need to be synchronous as well - ksmserver-logout-greeter specifically calls these
     // and will quit immediately after
-    m_login1->Suspend(true).waitForFinished();
+    notifySleepFailed(m_login1->Suspend(true), i18nc("@title:notification", "Could not go to sleep"));
 }

 void LogindSessionBackend::hybridSuspend()
 {
-    m_login1->HybridSleep(true).waitForFinished();
+    notifySleepFailed(m_login1->HybridSleep(true), i18nc("@title:notification", "Could not go to sleep"));
 }

 void LogindSessionBackend::hibernate()
 {
-    m_login1->Hibernate(true).waitForFinished();
+    notifySleepFailed(m_login1->Hibernate(true), i18nc("@title:notification", "Could not hibernate"));
 }

 void LogindSessionBackend::suspendThenHibernate()
 {
-    m_login1->SuspendThenHibernate(true).waitForFinished();
+    notifySleepFailed(m_login1->SuspendThenHibernate(true), i18nc("@title:notification", "Could not go to sleep"));
 }

 bool LogindSessionBackend::canShutdown() const
